from pathlib import Path
p=Path('work/factory.html');s=p.read_text(encoding='utf-8')
s=s.replace('.route b{color:#ffda77}', '.route b{color:#ff929c}')
s=s.replace('<button id="topBtn">위에서</button>', '<button id="compareBtn">바닥 비교</button><button id="topBtn">위에서</button>')
s=s.replace('<section><h2>목적 공간</h2>', '<section><h2>층별 바닥 범위</h2><p class="muted">1층: 사무실·계단만 표현<br>2층: 창고 포함 바닥<br>3층: 왼쪽 기숙사 부분만 바닥<br><b>3층 OPEN 아래는 2층 창고</b></p></section><section><h2>목적 공간</h2>')
s=s.replace('황색: 개구부·계단·경로<br>적색: 지정한 화점', '황색: 개구부·계단<br>적색: 진입경로·지정한 화점')
s=s.replace('경로는 선택한 층에서 계단 A·B의 문 앞을 시작점으로 계산합니다. 화점이 없으면 목적실 문에서 끝납니다. 외부 주출입구에서 목적지까지의 전체 경로와 층간 최단경로는 아직 제공하지 않습니다.', '경로는 외부에서 시작하여 서측 외부계단과 2층 방풍실 출입문을 통과합니다. 3층 목적지는 계단 A 또는 B로 수직 이동합니다. 화점이 없으면 목적실 문에서 끝납니다. 외부 접근 위치와 계단의 지면 연결은 임시 가정이며, 주출입구로 확인된 것은 아닙니다. 1층 연결은 근거가 없어 경로를 만들지 않았습니다. 붉은 경로는 가려진 아래층 구간도 투시 표시합니다.')
s=s.replace('최단거리는 0.25m 간격 통행 격자의 8방향 탐색 기준입니다.', '층내 최단거리는 0.25m 통행 격자 기준이며 외부 접근과 계단 이동의 3D 길이를 합산해 두 계단 후보를 비교합니다. 거리는 임시 높이에 따른 근사값입니다.')
s=s.replace('소방기계와 승강기는 확인되지 않아 표시하지 않습니다. 빨간 점은 사용자가 지정하는 화점이며 화재 예측 기능은 아닙니다.', '소방기계와 승강기는 확인되지 않아 표시하지 않습니다. 붉은 화살표는 진입경로이며, 빨간 점은 지정 화점입니다. 바닥 비교는 벽과 경로를 숨기고 세 층을 벌려 바닥 범위를 보여주는 설명 화면입니다. 펼쳐진 층 간격은 실제 높이가 아닙니다.')
p.write_text(s,encoding='utf-8')
p=Path('work/factory.js');s=p.read_text(encoding='utf-8')
s=s.replace("function setFloor(f){state.floor=String(f);", "function setFloor(f){const oldFloor=state.routeFloor,oldRoom=$('roomList').value;state.floor=String(f);")
s=s.replace("state.routeFloor=f==='all'?2:Number(f);", "state.routeFloor=f==='all'?oldFloor:Number(f);")
s=s.replace("fillRooms();updateRoutes();restore();$('notice')", "fillRooms();if(f==='all')$('roomList').value=oldRoom;updateRoutes();restore();$('notice')")
s=s.replace("if(state.floor==='all')setFloor('2');state.pick", "if(state.floor==='all'||state.compare)setFloor(String(state.routeFloor));state.pick")
s=s.replace('camera,D,ready:true}', 'camera,D,fullRoutes,stairTransfer,comparison,slabs,routeGroup,exteriorPath,entry2,ready:true}')
p.write_text(s,encoding='utf-8')
p=Path('outputs/당산리공장-모델안내.txt');s=p.read_text(encoding='utf-8')
s=s.replace('황색: 문·개구부·계단·경로. 적색: 사용자가 지정한 화점.', '황색: 문·개구부·계단. 적색: 외부 진입경로와 지정 화점.')
s=s.replace('- 경로는 선택 층의 계단문 A·B에서 목적실 문 또는 지정 화점까지.', '- 경로는 외부 → 외부계단(지면 연결 가정) → 2층 방풍실 출입문 → 목적실.\n  3층 목적지는 계단 A/B를 경유하는 두 경로를 전체 길이로 비교합니다.')
s=s.replace('- 경로 계산 결과는 층내 경로이며 외부 진입 및 층간 전체 경로가 아님.', '- 외부 위치·지면 높이는 임시 가정입니다. 주출입구로 확정한 경로가 아닙니다.\n- 바닥은 불투명 면과 밝은 테두리로 표현합니다. 바닥 비교 버튼으로\n  층을 벌려 1층 일부·2층 창고 포함·3층 기숙사 부분의 차이를 봅니다.\n  이 비교 화면의 층 간격은 실제 높이가 아닙니다.')
p.write_text(s,encoding='utf-8')
